                        break;
                    }
                }
            }
            let reply = match reply {
                Some(r) => r,
                None => {
                    stats.add(&usage, spent);
                    remember!();
                    let done = if tool_calls > 0 {
                        format!(
                            "；注意：此前 {tool_calls} 次工具改动已应用并保存到文件，可继续对话或 /history 回看"
                        )
                    } else {
                        String::new()
