                    return Err(format!(
                        "{}（已重试 {} 次）{done}",
                        last_llm_err.unwrap_or_default(),
                        self.max_llm_retries
                    ));
                }
            };
            let crate::chat::Reply { text: raw, usage: ru } = reply;
