                targets = geoms_ref.iter().map(|(id, g)| (id.clone(), g.0, t)).collect();
            } else if axis == "y" && mode == "bottom" {
                let t = geoms_ref.iter().map(|(_, g)| g.1 + g.3).fold(f64::NEG_INFINITY, f64::max);
