        assert!(err.contains("同时"), "{err}");
        assert_eq!(d.canonical(), before);
        // 什么都没给 → 明确报错
        let err2 = t.run(&mut d, "layout", &serde_json::json!({
            "move": [{"id": "svc-a"}]
