[hidden] { display: none !important; }

:root {
  --bg: #12141a; --panel: #1b1e27; --line: #2a2e3a; --fg: #dfe3ea;
  --dim: #8b93a5; --accent: #4f8cff; --ok: #4caf7d; --warn: #e0a63c; --err: #e5636b;
}
* { box-sizing: border-box; }
html, body { height: 100%; margin: 0; }
body {
  background: var(--bg); color: var(--fg);
  font: 13px/1.5 -apple-system, "PingFang SC", "Segoe UI", sans-serif;
  display: flex; flex-direction: column; overflow: hidden;
}
header {
  display: flex; align-items: center; gap: 8px;
  padding: 8px 12px; background: var(--panel); border-bottom: 1px solid var(--line);
}
.title { font-weight: 600; margin-right: 6px; }
.chip { padding: 2px 10px; border-radius: 10px; background: #242836; }
.dim { color: var(--dim); }
.spacer { flex: 1; }
button {
  background: #242836; color: var(--fg); border: 1px solid var(--line);
  border-radius: 6px; padding: 4px 12px; cursor: pointer; font: inherit;
}
button:hover { border-color: var(--accent); }
button.tool.active { background: var(--accent); border-color: var(--accent); color: #fff; }
#llm-banner {
  background: #3a2f14; color: var(--warn); padding: 6px 12px; font-size: 12px;
}
main { flex: 1; display: flex; min-height: 0; }
#canvas-wrap { flex: 1; position: relative; min-width: 0; }
#canvas { position: absolute; inset: 0; overflow: hidden; background:
  radial-gradient(#1e222c 1px, transparent 1px); background-size: 22px 22px;
  background-color: var(--bg); }
#canvas > div { overflow: hidden; }
#placeholder {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  color: var(--dim);
}
.rubber-band {
  position: absolute; border: 1px dashed var(--accent);
  background: rgba(79, 140, 255, 0.12); z-index: 10; pointer-events: none;
}
#hint {
  position: absolute; left: 10px; bottom: 8px; color: var(--dim); font-size: 12px;
  background: rgba(18, 20, 26, 0.8); padding: 3px 10px; border-radius: 10px;
}
#side {
  width: 340px; display: flex; flex-direction: column;
  border-left: 1px solid var(--line); background: var(--panel);
}
#chatlog { flex: 1; overflow-y: auto; padding: 10px; display: flex; flex-direction: column; gap: 8px; }
.msg { white-space: pre-wrap; word-break: break-word; }
.msg.user { align-self: flex-end; background: #26314a; border-radius: 10px; padding: 6px 10px; max-width: 90%; }
.msg.assistant { align-self: flex-start; color: var(--fg); max-width: 95%; }
.msg.tool-note { color: var(--dim); font-size: 12px; align-self: flex-start; }
.msg.error { color: var(--err); align-self: flex-start; }
.msg.ok { color: var(--ok); align-self: flex-start; font-size: 12px; }
#chatform { border-top: 1px solid var(--line); padding: 8px; display: flex; flex-direction: column; gap: 6px; }
textarea {
  width: 100%; resize: none; background: #12141a; color: var(--fg);
  border: 1px solid var(--line); border-radius: 8px; padding: 8px; font: inherit;
}
textarea:focus { outline: none; border-color: var(--accent); }
.row { display: flex; align-items: center; gap: 8px; }
#sel-note { flex: 1; color: var(--dim); font-size: 12px; }
#send { background: var(--accent); color: #fff; border: none; padding: 6px 18px; }
#send:disabled { opacity: 0.5; cursor: wait; }
.sel-chip {
  margin: 6px 10px 0; padding: 5px 10px; border: 1px solid var(--accent);
  border-radius: 8px; font-size: 12px; color: var(--accent);
}

/* ---- settings modal ---- */
.modal-backdrop {
  position: fixed; inset: 0; background: rgba(0, 0, 0, 0.55);
  display: flex; align-items: center; justify-content: center; z-index: 50;
}
.modal {
  background: var(--panel); border: 1px solid var(--line); border-radius: 12px;
  width: 460px; max-width: calc(100vw - 40px); max-height: 90vh; overflow-y: auto;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
}
.modal-head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 12px 16px; border-bottom: 1px solid var(--line);
}
.modal-head h2 { margin: 0; font-size: 15px; }
.icon-btn {
  background: none; border: none; color: var(--dim); font-size: 16px; padding: 2px 8px;
}
.icon-btn:hover { color: var(--fg); border: none; }
.settings-form { padding: 14px 16px; display: flex; flex-direction: column; gap: 12px; }
.panel-label { color: var(--dim); font-size: 12px; }
.cfg-current { background: #12141a; border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; }
.cfg-current-body { margin: 6px 0 0; display: grid; grid-template-columns: auto 1fr; gap: 2px 14px; }
.cfg-current-body dt { color: var(--dim); }
.cfg-current-body dd { margin: 0; word-break: break-all; }
.field { display: flex; flex-direction: column; gap: 4px; }
.field > span { color: var(--dim); font-size: 12px; }
.field input {
  background: #12141a; color: var(--fg); border: 1px solid var(--line);
  border-radius: 8px; padding: 8px 10px; font: inherit;
}
.field input:focus { outline: none; border-color: var(--accent); }
.field-static { color: var(--dim); font-size: 12px; }
.test-result {
  border-radius: 8px; padding: 8px 12px; font-size: 13px; white-space: pre-wrap;
}
.test-result.ok { background: #12281c; color: var(--ok); border: 1px solid #1d3a28; }
.test-result.err { background: #2a1418; color: var(--err); border: 1px solid #431f26; }
.modal-actions { display: flex; align-items: center; gap: 8px; margin-top: 4px; }
button.secondary { background: #242836; }
button.primary-btn { background: var(--accent); color: #fff; border: none; }

.grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
select.field, .field select {
  background: #12141a; color: var(--fg); border: 1px solid var(--line);
  border-radius: 8px; padding: 8px 10px; font: inherit;
}
#usage { max-width: 300px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#usage.warn { border-color: var(--warn); color: var(--warn); }
#send.danger { background: var(--err); }

.chat-divider { align-self: center; color: var(--dim); font-size: 11px; margin: 4px 0; }

.canvas-modes {
  position: absolute; right: 12px; bottom: 12px; z-index: 20;
  display: flex; gap: 6px; padding: 4px 6px;
  background: rgba(18, 20, 26, 0.85); border: 1px solid var(--line);
  border-radius: 10px;
}
.canvas-modes .tool { font-size: 12px; padding: 3px 10px; }
.mode-sep { width: 1px; height: 16px; background: var(--line); margin: 0 2px; }

.mini-editor {
  position: absolute; z-index: 40; padding: 2px 6px; font: inherit;
  background: #12141a; color: var(--fg); border: 1px solid var(--accent);
  border-radius: 4px; outline: none;
}

/* ---- 自绘 cell 手柄（resize 8 + rotate 1） ---- */
#cell-handles {
  position: absolute; left: 0; top: 0; width: 100%; height: 100%;
  pointer-events: none; z-index: 15;
}
.mx-handle { position: absolute; pointer-events: auto; box-sizing: border-box; }
.mx-handle-resize {
  width: 8px; height: 8px; background: #fff;
  border: 1.5px solid #0a84ff; border-radius: 1px;
}
.mx-handle-rotate {
  width: 14px; height: 14px; border-radius: 50%;
  background: #fff; border: 2px solid #0a84ff; cursor: grab;
}
.mx-handle-rotate::after {
  content: ''; position: absolute; left: 6px; top: 12px;
  width: 2px; height: 19px; background: #0a84ff; border-radius: 1px;
}

.mx-handle-rotate-flip::after { display: none; }
.mx-handle-rotate-flip::before {
  content: ''; position: absolute; left: 6px; top: -19px;
  width: 2px; height: 19px; background: #0a84ff; border-radius: 1px;
}

