         "path" => match config::config_file_path() {
             Some(p) => println!("{}", p.display()),
             None => {
                 eprintln!("找不到主目录（HOME/USERPROFILE 未设置）");
                 std::process::exit(1);
             }
         },
         other => {
             eprintln!("未知子命令: {other}（可用: show set clear path）");
             std::process::exit(2);
         }
     }
