 pub struct Issue {
     pub severity: &'static str, // "error" | "warning" | "info"
     pub kind: &'static str,
     pub ids: Vec<String>,
     pub detail: String,
 }

 #[derive(Debug, Clone, Default, serde::Serialize)]
 pub struct Stats {
     pub vertices: usize,
     pub edges: usize,
