display.text:
//! Emit the git short hash for build identification (debugging aid:
//! the web UI shows it, so a stale-binary report is instantly visible).
//! Also generates tool_specs.txt from TOOL_META (single source of truth).

use std::fs;
use std::path::Path;

fn main() {
    let hash = std::process::Command::new("git")
        .args(["rev-parse", "--short", "HEAD"])
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
        .unwrap_or_else(|| "unknown".to_string());
    println!("cargo:rustc-env=GIT_HASH={hash}");
    println!("cargo:rerun-if-changed=.git/HEAD");

    // Generate tool_specs.txt from tools_meta.rs
    generate_tool_specs();
    println!("cargo:rerun-if-changed=src/tools_meta.rs");
}

fn generate_tool_specs() {
    let meta_path = Path::new("src/tools_meta.rs");
    let content = fs::read_to_string(meta_path).expect("read tools_meta.rs");

    // Simple parser: extract (name, desc) pairs from TOOL_META array
    // Format: ( "name", "desc" ),
    let mut specs = String::new();
    let mut in_meta = false;
    let mut i = 0;

    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.starts_with("pub const TOOL_META:") {
            in_meta = true;
            continue;
        }
        if in_meta {
            if trimmed.starts_with(']') || trimmed.starts_with("};") {
                break;
            }
            // Match tuple entries: ( "name", "desc" ),
            if trimmed.starts_with('(') && trimmed.contains('"') {
                // Extract name and description
                // Simple approach: find first "name", then the description string
                if let Some(name_start) = trimmed.find('"') {
                    if let Some(name_end) = trimmed[name_start + 1..].find('"') {
                        let name = &trimmed[name_start + 1..name_start + 1 + name_end];
                        // Find the description (second string literal, starts with r#")
                        let after_name = &trimmed[name_start + 1 + name_end + 1..];
                        if let Some(desc_start) = after_name.find("r#\"") {
                            let desc_content = &after_name[desc_start + 3..];
                            if let Some(desc_end) = desc_content.find("\"#") {
                                let desc = &desc_content[..desc_end];
                                i += 1;
                                specs.push_str(&format!("{}. {}  {}\n\n", i, name, desc));
                            }
                        }
                    }
                }
            }
        }
    }

    // Add the closing protocol line
    specs.push_str(r#"任务完成用输出协议的结束信封 {"reply": "<给用户的总结>", "done": true}
（reply 会直接展示给用户）。"#);

    let out_dir = std::env::var("OUT_DIR").expect("OUT_DIR not set");
    let out_path = Path::new(&out_dir).join("tool_specs.txt");
    fs::write(&out_path, specs).expect("write tool_specs.txt");
}

