async fn api_chat_stream(
    State(app): State<AppState>,
    State(st): State<Arc<Mutex<WebState>>>,
    State(cancel): State<Arc<CancelSlot>>,
    Json(req): Json<ChatReq>,
) -> Response {
    let cfg = config::effective_settings().unwrap_or_default();
    // 短暂持锁：检查忙/配置/会话，把会话"拿走"。槽位为空 = 忙，
    // 这是唯一的并发信号；归还发生在任务收尾（所有退出路径都走同一条）。
    let taken = {
        let mut st = st.lock().await;
        if st.running.is_some() {
            return Json(json!({
                "type": "error",
                "error": "另一个任务正在运行中——先点「停止」或等它完成"
            }))
            .into_response();
        }
        if st.chat.is_none() {
            return Json(json!({
                "type": "error",
                "error": "LLM 未配置：点右上角 ⚙ 填写并保存"
            }))
            .into_response();
        }
        let Some(cur) = st.current.clone() else {
            return Json(json!({
                "type": "error",
                "error": "还没有打开的会话：先点「＋ 新建会话」"
            }))
            .into_response();
        };
        let ss = match st.sessions.remove(&cur) {
            Some(ss) => ss,
            None => {
                return Json(json!({
                    "type": "error",
                    "error": "会话未加载"
                })).into_response();
            }
        };
        let budget = cfg.budget_yuan;
        st.budget_yuan = budget;
        st.running = Some(cur.clone());
        st.snapshot = RunningSnapshot {
            name: cur.clone(),
            cells: ss.doc.cells.len(),
            lines: ss.doc.canonical().lines().count(),
            usage_in: ss.stats.usage.input_tokens,
            usage_out: ss.stats.usage.output_tokens,
            cost_yuan: ss.stats.cost_yuan,
        };
        let chat = match st.chat.clone() {
            Some(c) => c,
            None => {
                return Json(json!({
                    "type": "error",
                    "error": "LLM 未配置"
                })).into_response();
            }
        };
    };
    let (cur, ss, _, mut tools, budget_yuan) = taken;
    let SessionState { mut doc, mut stats } = ss;

    // 模型 view 复用共享热 chromium（与人工导出同一进程，懒启动一次、
    // 之后热页面渲染）——否则每个 ask 的 clone 都会自带懒启动并在
    // ask 结束时杀掉浏览器进程。启动失败时回退 Tools 自带的懒启动路径。
    match ensure_shared_renderer(&app).await {
        Ok(r) => tools.renderer = Some(r),
        Err(e) => eprintln!("共享 chromium 未就绪（view 回退懒启动）: {e}"),
    }

    let (tx, rx) = mpsc::channel::<Vec<u8>>(128);
    let st2 = st.clone();
