    // 直接读磁盘：每次 edit 都即时落盘，运行中画布也能拿到最新内容，
    // 完全不需要等锁。
    let path = {
        let st = st.lock().await;
        match &st.current {
            Some(cur) => st.dir.join(cur),
            None => return (StatusCode::NOT_FOUND, "no session").into_response(),
        }
    };

