                         reply = format!(
                             "{reply}\n\n（系统提示：本轮模型未调用任何工具，文件没有被修改。如果这与你的要求不符，请重新表述并强调要用工具修改。）"
                         );
                     }
                     emit!(EngineEvent::Final { reply: reply.clone() });
                     stats.add(&usage, spent);
                     remember!();
                     return Ok(TurnOutcome {
                         reply,
                         tool_calls: 0,
                         envelopes: vec![raw.clone()],
