     if (!d || typeof d !== 'object') return;
     if (d.event) diag('msg:' + d.event);
     if (d.event === 'init') {
       booted = true;
       window.__ready = true;
       if (pendingRun) { var r = pendingRun; pendingRun = null; r(); }
       else if (params.xml) {
         f.contentWindow.postMessage(JSON.stringify({ action: 'load', autosave: 1, xml: params.xml }), '*');
       }
     }
