     }
     if (d.event === 'export') {
       var data = d.data || '';
       var m = data.match(/^data:image\/png;base64,([\s\S]*)$/);
       window.__exportPng = m ? m[1] : data;
       window.__exportDone = true;
       if (pendingResolve) { var rs = pendingResolve; pendingResolve = null; rs({ ok: true, png: window.__exportPng }); }
     }
   });
