/// Parse + re-emit in canonical layout. Idempotent: canonical input maps to
/// itself byte-for-byte (asserted in tests). Attribute order is preserved;
/// entity escaping is normalized to one canonical policy.
/// 
/// If `legacy_mode` is true, applies 2018 viewer compatibility normalization
/// (e.g. `ellipse` -> `shape=ellipse`, `shape=mxgraph.basic.ellipse` -> `shape=ellipse`).
pub fn canonicalize(xml: &str, legacy_mode: bool) -> Result<String, XmlError> {
    let mut roots = parse_nodes(xml, legacy_mode)?;
    expand_diagrams(&mut roots)?;
    let mut em = Emitter {
        out: String::new(),
    };
    for n in &roots {
        em.node(0, n);
    }
    Ok(em.out)
}

/// Backward compatibility: canonicalize without legacy mode.
pub fn canonicalize_legacy(xml: &str) -> Result<String, XmlError> {
    canonicalize(xml, true)
}

