 fn static_text(s: &'static str, ct: &'static str) -> Response {
     static_bytes(s.as_bytes().to_vec(), ct)
 }

 fn static_bytes(bytes: Vec<u8>, ct: &'static str) -> Response {
     (
         StatusCode::OK,
         [(header::CONTENT_TYPE, ct)],
         bytes,
     )
         .into_response()
 }


