/// Apply a textual edit over `[start..=end]` lines: validate, canonicalize,
/// re-index, diff, then commit. Nothing is written to disk here; the caller
/// saves (REPL saves after every applied edit).
pub fn apply_edit(
    &mut self,
    start: usize,
    end: usize,
    replacement: &str,
