                 println!("budget:   {:?}", s.budget_yuan);
             }
             None => {
                 eprintln!("未配置 LLM。保存方式: drawio-harness config set --base-url <url> --model <model> [--api-key <key>]");
                 std::process::exit(1);
             }
         },
