     let sessions: Vec<serde_json::Value> = files
         .iter()
         .map(|p| {
             let name = p
                 .file_name()
                 .map(|f| f.to_string_lossy().into_owned())
                 .unwrap_or_default();
             let running = st.running.as_deref() == Some(name.as_str());
