-                Some(ss) => (Some(ss.doc.cells.len()), true),
+                Some(ss) => (Some(ss.doc.cells().len()), true),
                 None if running => (Some(st.snapshot.cells), true),
                 None => (None, false),
             };
             json!({
                 "name": name,
                 "size": std::fs::metadata(p).map(|m| m.len()).unwrap_or(0),
                 "loaded": loaded,
                 "cells": cells,
                 "busy": running,
