         .split(';')
         .map(|p| p.trim())
         .filter(|p| !p.is_empty())
         .collect();
     if parts.is_empty() {
         return style.to_string();
     }
     let mut out: Vec<String> = parts.iter().map(|p| p.to_string()).collect();
     // 1) shape=mxgraph.basic.X -> shape=X
