+    fn envelope_parses_plain_and_fenced() {
+        let v = parse_envelope(r#"{"tool":"read","args":{"query":"a"}}"#).unwrap();
+        assert_eq!(v["tool"], "read");
+        let v = parse_envelope("```json\n{\"reply\":\"好\",\"done\":true}\n```").unwrap();
