+        async fn complete(
+            &mut self,
+            _m: &[Message],
+            _o: &CallOpts,
+        ) -> Result<crate::chat::Reply, crate::chat::ChatError> {
+            self.calls += 1;
+            if self.failures_left > 0 {
+                self.failures_left -= 1;
+                Err(crate::chat::ChatError::Api("HTTP 500 Internal Server Error".into()))
+            } else {
