 /// One engine event -> one NDJSON line for the frontend.
 fn event_line(ev: &EngineEvent) -> serde_json::Value {
     match ev {
         EngineEvent::Turn { index } => json!({ "type": "turn", "index": index }),
         EngineEvent::ModelOutput { raw } => json!({
             "type": "model",
             "preview": truncate_utf8(raw, 300),
         }),
         EngineEvent::Tool { name, args } => json!({
             "type": "tool",
             "name": name,
             "args": truncate_utf8(args, 200),
         }),
         EngineEvent::ToolResult { name, text, has_image } => json!({
             "type": "tool_result",
             "name": name,
             "preview": text.lines().next().unwrap_or("").chars().take(200).collect::<String>(),
             "has_image": has_image,
         }),
         EngineEvent::Usage { usage, cost_yuan } => json!({
             "type": "usage",
             "in": usage.input_tokens,
             "out": usage.output_tokens,
             "cost_yuan": cost_yuan,
         }),
         EngineEvent::Final { reply } => json!({ "type": "reply", "reply": reply }),
     }
 }

 fn truncate_utf8(s: &str, n: usize) -> String {
     s.chars().take(n).collect()
 }

 async fn api_chat_stream(
     State(app): State<AppState>,
     State(st): State<Arc<Mutex<WebState>>>,
     State(cancel): State<Arc<CancelSlot>>,
     Json(req): Json<ChatReq>,
 ) -> Response {
     let cfg = config::effective_settings().unwrap_or_default();
     // 短暂持锁：检查忙/配置/会话，把会话"拿走"。槽位为空 = 忙，
     // 这是唯一的并发信号；归还发生在任务收尾（所有退出路径都走同一条）。
     let (cur, ss, mut chat, mut tools, budget_yuan) = {
         let mut st = st.lock().await;
         if st.running.is_some() {
             return Json(json!({
                 "type": "error",
                 "error": "另一个任务正在运行中——先点「停止」或等它完成"
             }))
             .into_response();
         }
         if st.chat.is_none() {
             return Json(json!({
                 "type": "error",
                 "error": "LLM 未配置：点右上角 ⚙ 填写并保存"
             }))
             .into_response();
         }
         let Some(cur) = st.current.clone() else {
             return Json(json!({
                 "type": "error",
                 "error": "还没有打开的会话：先点「＋ 新建会话」"
             }))
             .into_response();
         };
         let ss = match st.sessions.remove(&cur) {
             Some(ss) => ss,
             None => {
                 return Json(json!({
                     "type": "error",
                     "error": "会话未加载"
                 })).into_response();
             }
         };
         let budget = cfg.budget_yuan;
         st.budget_yuan = budget;
         st.running = Some(cur.clone());
         st.snapshot = RunningSnapshot {
             name: cur.clone(),
             cells: ss.doc.cells().len(),
             lines: ss.doc.canonical().lines().count(),
             usage_in: ss.stats.usage.input_tokens,
             usage_out: ss.stats.usage.output_tokens,
             cost_yuan: ss.stats.cost_yuan,
         };
         let chat = match st.chat.clone() {
             Some(c) => c,
             None => {
                 return Json(json!({
                     "type": "error",
                     "error": "LLM 未配置"
                 })).into_response();
             }
         };
         (cur, ss, chat, st.tools.clone(), budget)
     };
     let SessionState { mut doc, mut stats } = ss;

     // 模型 view 复用共享热 chromium（与人工导出同一进程，懒启动一次、
     // 之后热页面渲染）——否则每个 ask 的 clone 都会自带懒启动并在
     // ask 结束时杀掉浏览器进程。启动失败时回退 Tools 自带的懒启动路径。
     match ensure_shared_renderer(&app).await {
         Ok(r) => tools.renderer = Some(r),
         Err(e) => eprintln!("共享 chromium 未就绪（view 回退懒启动）: {e}"),
     }

     let (tx, rx) = mpsc::channel::<Vec<u8>>(128);
     let st2 = st.clone();
     let cancel2 = cancel.clone();
     let cancel_flag = Arc::new(std::sync::atomic::AtomicBool::new(false));
     if let Ok(mut g) = cancel.flag.lock() {
         *g = Some(cancel_flag.clone());
     }

     let _task = tokio::spawn(async move {
         let opts = {
             let mut o = crate::engine::RunOpts::from_settings(&cfg);
             if let Some(b) = budget_yuan {
                 o.budget_remaining = (b - stats.cost_yuan).max(0.0);
             }
             o.legacy_viewer = !drawio_agent_renderer::drawio_app_cached();
             o
         };
         // Canvas selection -> @cell refs (same as REPL /sel)。
         let ctx = selection_ctx(&req.cell_ids, &doc);
         let harness = Harness {
             max_turns: opts.max_turns.max(1),
             ..Default::default()
         };
         let tx2 = tx.clone();
         let events: Arc<std::sync::Mutex<Vec<serde_json::Value>>> = Arc::default();
         let events2 = events.clone();
         let progress: ProgressFn = Arc::new(move |ev: EngineEvent| {
             let line = event_line(&ev);
             if let Ok(mut v) = events2.lock() {
                 v.push(line.clone());
             }
             let _ = tx2.try_send(format!("{line}\n").into_bytes());
         });

         // 监视器：客户端断开（页面刷新/关闭）或用户点「停止」→ 引擎被
         // select 取消（drop 掉当前 await 的网络调用），任务走正常收尾。
         let flag2 = cancel_flag.clone();
         let tx3 = tx.clone();
         let monitor = async move {
             loop {
                 tokio::time::sleep(std::time::Duration::from_millis(500)).await;
                 if tx3.is_closed() || flag2.load(std::sync::atomic::Ordering::SeqCst) {
                     return;
                 }
             }
         };
         // 主 ask；结束后若全程未 view 且改过图，自动追加一次独立自检轮。
         const SELFCHECK_TEXT: &str =
-            "（自动自检）你刚完成绘图但全程没有用 view 查看成图。请：调用一次 view              检查布局/箭头/间距是否符合图意；有明显问题（重叠/穿线/缺箭头）修最明显的              1-2 处即可，不必追求完美；然后简短总结收尾。";
+            "（自动自检）你刚才修改了图但全程没有用 view 查看成图。请：调用一次 view 检查布局/箭头/间距是否符合图意；有明显问题（重叠/穿线/缺箭头）修最明显的 1-2 处即可，不必追求完美；然后简短总结收尾。";
         let progress_opt: Option<ProgressFn> = Some(progress);
         let run_main = harness.run(
             &mut chat,
             &mut tools,
             &mut doc,
             &req.text,
             &ctx,
             &opts,
             &mut stats,
             &progress_opt,
         );
         let outcome = tokio::select! {
             _ = monitor => Err("已停止（客户端断开或用户取消）".to_string()),
             r = run_main => r,
         };
         let mut outcome2: Option<Result<TurnOutcome, String>> = None;
         // 自检轮判定：主 ask 成功、改过图（draw/edit）、全程无 view、连接还在
         if outcome.is_ok() && !tx.is_closed() {
             let evs = events.lock().map(|v| v.clone()).unwrap_or_default();
             let has_edit = evs.iter().any(|e| {
                 e.get("name").and_then(|v| v.as_str()).is_some_and(|n| matches!(n, "draw" | "edit"))
             });
             let has_view = evs.iter().any(|e| {
                 e.get("name").and_then(|v| v.as_str()) == Some("view")
             });
             if has_edit && !has_view {
                 if let Ok(mut v) = events.lock() {
                     v.push(json!({ "type": "ask_sep" }));
                 }
                 let _ = tx
                     .send(
                         format!(
                             "{}\n",
                             json!({ "type": "tool-note", "text": "（自动自检）本轮已改图但未 view——追加一次质量自检…" })
                         )
                         .into_bytes(),
                     )
                     .await;
                 // 第二监视器（同一取消语义）
                 let flag2b = cancel_flag.clone();
                 let tx3b = tx.clone();
                 let monitor2 = async move {
                     loop {
                         tokio::time::sleep(std::time::Duration::from_millis(500)).await;
                         if tx3b.is_closed() || flag2b.load(std::sync::atomic::Ordering::SeqCst) {
                             return;
                         }
                     }
                 };
                 let run_self = harness.run(
                     &mut chat,
                     &mut tools,
                     &mut doc,
                     SELFCHECK_TEXT,
                     "",
                     &opts,
                     &mut stats,
                     &progress_opt,
                 );
                 outcome2 = Some(tokio::select! {
                     _ = monitor2 => Err("已停止（客户端断开或用户取消）".to_string()),
                     r = run_self => r,
                 });
             }
         }
         let disconnected = tx.is_closed();

         // 事件收尾：断开时接收端已不在，跳过发送
         if !disconnected {
             match &outcome {
                 Ok(o) => {
                     let _ = tx
                         .send(
                             format!(
                                 "{}\n",
                                 json!({
                                     "type": "done",
                                     "tool_calls": o.tool_calls,
                                     "session": json!({
                                         "in": stats.usage.input_tokens,
                                         "out": stats.usage.output_tokens,
                                         "cost_yuan": stats.cost_yuan,
                                         "budget_yuan": budget_yuan,
                                     }),
                                 })
                             )
                             .into_bytes(),
                         )
                         .await;
                 }
                 Err(e) => {
                     let _ = tx
                         .send(format!("{}\n", json!({ "type": "error", "error": e })).into_bytes())
                         .await;
                 }
             }
         }
         // 历史记录：只记录真正完成的任务（断开/取消不污染聊天重放）
         if !disconnected {
             // 无论成功失败都落盘轨迹。事件按 ask_sep 分隔主 ask 与自检轮，
             // 各自一条记录；用量主条取 outcome.usage，自检条 = 总计 − 主条。
             let evs_all = events.lock().map(|v| v.clone()).unwrap_or_default();
             let sep = evs_all.iter().position(|e| e.get("type").and_then(|v| v.as_str()) == Some("ask_sep"));
             let (evs_main, evs_self): (&[serde_json::Value], &[serde_json::Value]) = match sep {
                 Some(p) => evs_all.split_at(p),
                 None => (&evs_all[..], &[]),
             };
             let usage_main = match &outcome {
                 Ok(o) => (o.usage.input_tokens, o.usage.output_tokens),
                 Err(_) => (0, 0),
             };
             let mk_rec = |user: &str, evs: &[serde_json::Value],
                               out: &Result<TurnOutcome, String>,
                               ui: u64, uo: u64| {
                 let (reply, error) = match out {
                     Ok(o) => (o.reply.clone(), None),
                     Err(e) => (String::new(), Some(e.to_string())),
                 };
                 let calls = match out {
                     Ok(o) => o.tool_calls as u32,
                     Err(_) => evs.iter().filter(|ev| ev.get("name").is_some()).count() as u32,
                 };
                 HistoryRec {
                     ts: history::now_secs(),
                     user: user.to_string(),
                     reply,
                     tool_calls: calls,
                     usage_in: ui,
                     usage_out: uo,
                     cost_yuan: stats.cost_yuan,
                     events: evs.to_vec(),
                     xml: doc.canonical().to_string(),
                     error,
                 }
             };
             let rec1 = mk_rec(
                 &req.text,
                 evs_main,
                 &outcome,
                 usage_main.0,
                 usage_main.1,
             );
             if let Err(e) = history::append(&history::history_path(&doc.path), &rec1) {
                 eprintln!("history 落盘失败: {e}");
             }
             if let Some(o2) = &outcome2 {
                 let self_usage = (
                     stats.usage.input_tokens.saturating_sub(usage_main.0),
                     stats.usage.output_tokens.saturating_sub(usage_main.1),
                 );
                 let rec2 = mk_rec(
                     SELFCHECK_TEXT,
                     &evs_self[1..], // 跳过 ask_sep
                     o2,
                     self_usage.0,
                     self_usage.1,
                 );
                 if let Err(e) = history::append(&history::history_path(&doc.path), &rec2) {
                     eprintln!("history 落盘失败: {e}");
                 }
             }
         }
         // 记忆/用量无论如何落盘
         let _ = history::save_session_state(&doc.path, &stats);

         // 归还：唯一收尾路径，槽位不可能被卡死
         {
             let mut st = st2.lock().await;
             if st.running.as_deref() == Some(cur.as_str()) {
                 st.running = None;
                 st.snapshot = RunningSnapshot {
                     name: cur.clone(),
                     cells: doc.cells().len(),
                     lines: doc.canonical().lines().count(),
                     usage_in: stats.usage.input_tokens,
                     usage_out: stats.usage.output_tokens,
                     cost_yuan: stats.cost_yuan,
                 };
                 st.sessions.insert(cur, SessionState { doc, stats });
             }
         }
         // 清取消槽
         if let Ok(mut g) = cancel2.flag.lock() {
             *g = None;
         }
     });

     let stream = ReceiverStream::new(rx).map(|bytes| Ok::<_, std::io::Error>(axum::body::Bytes::from(bytes)));
     (
         axum::http::StatusCode::OK,
         [(header::CONTENT_TYPE, "application/x-ndjson")],
         Body::from_stream(stream),
     )
         .into_response()
 }

 async fn api_chat_cancel(
     State(cancel): State<Arc<CancelSlot>>,
 ) -> Json<serde_json::Value> {
     let flag = cancel
         .flag
         .lock()
         .ok()
         .and_then(|g| g.clone());
     match flag {
         Some(f) => {
             f.store(true, std::sync::atomic::Ordering::SeqCst);
             Json(json!({ "ok": true, "note": "已停止" }))
         }
         None => Json(json!({ "ok": false, "error": "当前没有运行中的任务" })),
     }
 }

