+/// 编辑被拒绝时的教学提示：解析失败（标签不配对是最常见死因）给整文件
+/// 骨架；其余（断引用等）给单 cell 正确形态——错误体本身已指明具体问题。
+fn reject_hint(e: &XmlError) -> &'static str {
+    match e {
+        XmlError::Xml(_) | XmlError::BlobDecode(_) => concat!(
