             .run(&mut chat, &mut tools, &mut doc, "hi", "", &RunOpts::default(), &mut SessionStats::default(), &None)
             .await
             .unwrap();
         assert_eq!(outcome.reply, "ok");
         assert_eq!(chat.calls, 2, "一次失败 + 一次成功");
