/// off_range 判定：changed cell 的**前置** span 是否触及任一请求区间。
/// 必须用前置 span：本次插入/删除会使后置 span 整体漂移，用后置 span
/// 会把模型明确请求过的 cell 误报为越界（E2E 实测）。溢出吞噬（替换
/// 文本未闭合吞掉邻行 cell）在前置 span 下依然能被抓到。
fn off_range_spans<'a>(
    pre: &'a [CellSpan],
    changed: &[String],
    ranges: &[(usize, usize)],
) -> Vec<String> {
    let mut out = Vec::new();
    for id in changed {
        let Some(span) = pre.iter().find(|c| &c.id == id) else { continue };
        let touches = ranges.iter().any(|&(s, e)| !(span.end_line < s || span.start_line > e));
        if !touches {
            out.push(id.clone());
        }
    }
    out
}
