                                tag: String::from_utf8_lossy(e.name().as_ref()).into_owned(),
                                start_line: line_of(&starts, pos_before),
                                end_line: line_of(&starts, pos_after),
                                start_byte: pos_before,
                                end_byte: pos_after,
                            };
