                                    )));
                                }
                                out.push(span);
                            }
                        }
                    }
                    _ => {}
                }
            }
            Err(e) => return Err(XmlError::Xml(format!("{e}"))),
        }
    }
    out.sort_by_key(|c| c.start_line);
    Ok(out)
