     #[tokio::test]
     async fn view_skips_render_when_doc_unchanged() {
         let mock = drawio_agent_renderer::MockDriver::new();
         let renderer =
             drawio_agent_renderer::Renderer::new(std::sync::Arc::new(mock.clone()));
         let mut tools = Tools::with_renderer(renderer);
