 }

 async fn api_chat_cancel(
     State(cancel): State<Arc<CancelSlot>>,
 ) -> Json<serde_json::Value> {
     let flag = cancel
         .flag
         .lock()
         .ok()
         .and_then(|g| g.clone());
     match flag {
         Some(f) => {
             f.store(true, std::sync::atomic::Ordering::SeqCst);
             Json(json!({ "ok": true, "note": "已停止" }))
         }
         None => Json(json!({ "ok": false, "error": "当前没有运行中的任务" })),
     }
 }

