 /// 导出当前会话为 PNG：读磁盘上的 canonical XML（与 /api/file 同一路径，
 /// 不受任务锁影响），chromium 2x 渲染返回。
 #[derive(Debug, serde::Deserialize)]
 struct ExportQuery {
     annotate: Option<bool>,
     focus: Option<String>,
 }

 /// 共享热渲染器：整个服务器进程只有一个 chromium 实例 + 热页面，
 /// 模型 view 与人工导出（/api/export/png）共用。懒启动一次；失败返回
 /// Err（调用方回退各自兜底路径）。Renderer 包装很薄，每次调用新建、
 /// 浏览器进程由槽位持有，不会随 Renderer drop 被杀。
 async fn ensure_shared_renderer(
     app: &AppState,
 ) -> Result<Arc<drawio_agent_renderer::Renderer>, String> {
     let mut slot = app.renderer.lock().await;
     if slot.is_none() {
         match drawio_agent_renderer::HeadlessChromiumDriver::launch().await {
             Ok(d) => *slot = Some(Arc::new(d)),
             Err(e) => return Err(format!("chromium 启动失败: {e}")),
         }
     }
     let driver = slot.clone().ok_or_else(|| "driver not initialized".to_string())?;
     Ok(Arc::new(drawio_agent_renderer::Renderer::new(driver)))
 }

 async fn api_export_png(
     State(app): State<AppState>,
     axum::extract::Query(q): axum::extract::Query<ExportQuery>,
 ) -> Response {
     let (path, stem) = {
         let st = app.big.lock().await;
         match &st.current {
             Some(cur) => (
                 st.dir.join(cur),
                 cur.trim_end_matches(".drawio").to_string(),
             ),
             None => return (StatusCode::NOT_FOUND, "no session").into_response(),
         }
     };
     let xml = match std::fs::read_to_string(&path) {
         Ok(x) => x,
         Err(_) => return (StatusCode::NOT_FOUND, "no session file").into_response(),
     };
     // 复用共享 driver（懒启动一次，之后热页面渲染）
     let renderer = match ensure_shared_renderer(&app).await {
         Ok(r) => r,
         Err(e) => {
             return (StatusCode::INTERNAL_SERVER_ERROR, e).into_response()
         }
     };
     let opts = drawio_agent_renderer::RenderOptions {
         scale: 2.0,
         annotate: q.annotate.unwrap_or(false),
         focus: q
             .focus
             .map(|f| f.split(',').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect())
             .unwrap_or_default(),
         ..Default::default()
     };
     match renderer.render(&xml, &opts).await {
         Ok(png) => (
             StatusCode::OK,
             [
                 (header::CONTENT_TYPE, "image/png"),
                 (
                     header::CONTENT_DISPOSITION,
                     &format!("attachment; filename=\"{stem}.png\""),
                 ),
             ],
             png,
         )
             .into_response(),
         Err(e) => (
             StatusCode::INTERNAL_SERVER_ERROR,
             format!("渲染失败: {e}"),
         )
             .into_response(),
     }
 }

 async fn api_manual(
     State(st): State<Arc<Mutex<WebState>>>,
     Json(req): Json<ManualReq>,
 ) -> Json<serde_json::Value> {
     let mut st = st.lock().await;
     if st.running.is_some() {
         return Json(json!({ "ok": false, "error": "任务运行中——先点「停止」或等它完成" }));
     }
     let Some(cur) = st.current.clone() else { return current_err() };
     let Some(ss) = st.sessions.get_mut(&cur) else { return busy_err() };
     let path = ss.doc.path.clone();
     match XmlDoc::from_text_at_with_legacy(&req.xml, &path, !drawio_agent_renderer::drawio_app_cached()) {
         Ok(d) => {
             let cells = d.cells().len();
             let lines = d.canonical().lines().count();
             ss.doc = d;
             let _ = ss.doc.save();
             let _ = history::save_session_state(&ss.doc.path, &ss.stats);
             Json(json!({ "ok": true, "cells": cells, "lines": lines, "xml": ss.doc.canonical() }))
         }
         Err(e) => Json(json!({ "ok": false, "error": format!("同步被拒绝（文件未改动）: {e}") })),
     }
 }
