   const walk = (c) => {
     if (c.geometry && !model.isEdge(c)) {
       x0 = Math.min(x0, c.geometry.x);
       y0 = Math.min(y0, c.geometry.y);
       x1 = Math.max(x1, c.geometry.x + (c.geometry.width || 0));
