        assert!(needs_selfcheck(&[tool("draw"), tool("view"), tool("edit")]));
        // 只看没改 → 不自检
        assert!(!needs_selfcheck(&[tool("view"), tool("read")]));
        // 空事件 → 不自检
        assert!(!needs_selfcheck(&[]));
    }
}
