             budget_remaining: 0.001,
             ..Default::default()
         };
         let err = Harness::default()
             .run(&mut fake2, &mut tools, &mut doc, "hi", "", &opts_broke, &mut SessionStats::default(), &None)
             .await
             .unwrap_err();
         assert!(err.contains("预算"), "{err}");
         assert_eq!(fake2.snapshots.len(), 1, "预算用尽后不应再发起调用");
     }

