                     )))
                 }
                 Err(e) => Err(format!("draw 被拒绝（文件未改动）: {e}\n{}", reject_hint(&e))),
             };
         }
         // 批量：ranges=[{range,text},...] 一次全做（全或无）；兼容旧单区间
         let batch: Vec<(usize, usize, String)> = if let Some(ranges) = args.get("ranges") {
             let arr = ranges
                 .as_array()
                 .ok_or_else(|| "ranges 需要是数组".to_string())?;
             if arr.is_empty() {
