                 match e.name().as_ref() {
                     b"mxGeometry" => {
                         if let Some(c) = cur.as_mut() {
                             for attr in e.attributes().flatten() {
                                 let key = attr.key.as_ref();
                                 let val = attr
                                     .unescape_value()
                                     .unwrap_or_default()
                                     .into_owned();
                                 let f = val.parse::<f64>().unwrap_or(0.0);
                                 match key {
                                     b"x" => c.x = f,
                                     b"y" => c.y = f,
                                     b"width" => c.w = f,
                                     b"height" => c.h = f,
                                     _ => {}
                                 }
                             }
                         }
                     }
                     b"mxPoint" => {
                         if let (true, Some(c)) = (in_array, cur.as_mut()) {
                             let mut px = 0.0;
                             let mut py = 0.0;
                             for attr in e.attributes().flatten() {
                                 let key = attr.key.as_ref();
                                 let val = attr
                                     .unescape_value()
                                     .unwrap_or_default()
                                     .into_owned();
                                 let f = val.parse::<f64>().unwrap_or(0.0);
