===================================================================
--- crates/harness/src/metrics.rs	
+++ crates/harness/src/metrics.rs	
@@ -1,988 +1,997 @@
 //! Deterministic geometric quality metrics for a drawio diagram.
 //!
 //! 分层设计（与调研计划一致）：
 //! - **errors**：客观缺陷（引用断掉）——人类几乎必然判错
 //! - **warnings**：强代理指标（重叠/交叉/标签溢出/越界）——需要阈值，
 //!   报告中带 cell id 供修复
 //! - **info**：弱代理（孤立节点、近似对齐组）——只报告不评判
 //!
 //! 全部从 XML 几何计算，不依赖 LLM。lint 工具与 `metrics` CLI 共用。

 use quick_xml::events::Event;
 use quick_xml::Reader;

 #[derive(Debug, Clone, Default)]
 pub struct GeomCell {
     pub id: String,
     pub parent: String,
     pub x: f64,
     pub y: f64,
     pub w: f64,
     pub h: f64,
     pub value: String,
     pub font_size: f64,
     pub is_edge: bool,
     /// style 原文（判断正交路由等）
     pub style: String,
     pub source: Option<String>,
     pub target: Option<String>,
     /// 折线拐点（edge 专属，模型坐标）
     pub points: Vec<(f64, f64)>,
 }

 #[derive(Debug, Clone, serde::Serialize)]
 pub struct Issue {
     pub severity: &'static str, // "error" | "warning" | "info"
     pub kind: &'static str,
     pub ids: Vec<String>,
     pub detail: String,
 }

 #[derive(Debug, Clone, Default, serde::Serialize)]
 pub struct Stats {
     pub vertices: usize,
     pub edges: usize,
     pub errors: usize,
     pub overlaps: usize,
     pub crossings: usize,
     pub label_overflows: usize,
     pub out_of_bounds: usize,
     pub isolated: usize,
     pub near_aligned_pairs: usize,
     /// 同一源的分支节点未按流向平行摆放（来自人类校准反馈）
     pub branch_misaligned: usize,
     /// 长直边（无正交路由）数量——斜穿遮挡的主因
     pub straight_edges: usize,
 }

 #[derive(Debug, Default, serde::Serialize)]
 pub struct Report {
     pub errors: Vec<Issue>,
     pub warnings: Vec<Issue>,
     pub info: Vec<Issue>,
     pub stats: Stats,
 }

 /// (cells, page 尺寸) 解析结果。
 type ParseGeom = (Vec<GeomCell>, Option<(f64, f64)>);

 /// 解析 canonical XML 中的 cell 几何（mxCell + mxGeometry + mxPoint）。
 use std::collections::HashMap;

 pub fn parse_geom(xml: &str) -> Result<ParseGeom, String> {
     let mut reader = Reader::from_str(xml);
     reader.config_mut().trim_text(true);
     let mut cells: Vec<GeomCell> = Vec::new();
     let mut cur: Option<GeomCell> = None;
     let mut in_array = false;
     let mut page: Option<(f64, f64)> = None;
     let mut buf = Vec::new();
     loop {
         match reader.read_event_into(&mut buf) {
             Ok(Event::Start(e)) => {
                 match e.name().as_ref() {
                     b"mxGraphModel" => {
                         let a = e.attributes();
                         let mut pw: Option<f64> = None;
                         let mut ph: Option<f64> = None;
                         for attr in a.flatten() {
                             let key = attr.key.as_ref();
                             let val = attr
                                 .unescape_value()
                                 .unwrap_or_default()
                                 .into_owned();
                             if key == b"pageWidth" {
                                 pw = val.parse().ok();
                             } else if key == b"pageHeight" {
                                 ph = val.parse().ok();
                             }
                         }
                         if let (Some(w), Some(h)) = (pw, ph) {
                             page = Some((w, h));
                         }
                     }
                     b"mxCell" => {
                         let mut c = GeomCell::default();
                         for attr in e.attributes().flatten() {
                             let key = attr.key.as_ref();
                             let val = attr
                                 .unescape_value()
                                 .unwrap_or_default()
                                 .into_owned();
                             match key {
                                 b"id" => c.id = val,
                                 b"parent" => c.parent = val,
                                 b"value" => c.value = val,
                                 b"source" => c.source = Some(val),
                                 b"target" => c.target = Some(val),
                                 b"edge" => c.is_edge = val == "1",
                                 b"style" => c.style = val,
                                 _ => {}
                             }
                         }
                         cur = Some(c);                        in_array = false;
                     }
                     b"mxGeometry" => {                        if let Some(c) = cur.as_mut() {
                             for attr in e.attributes().flatten() {
                                 let key = attr.key.as_ref();
                                 let val = attr
                                     .unescape_value()
                                     .unwrap_or_default()
                                     .into_owned();
                                 let f = val.parse::<f64>().unwrap_or(0.0);
                                 match key {
                                     b"x" => c.x = f,
                                     b"y" => c.y = f,
                                     b"width" => c.w = f,
                                     b"height" => c.h = f,
                                     _ => {}
                                 }
                             }
                         }
                     }
                     b"Array" => in_array = true,
                     b"mxPoint" => {
                         if let (true, Some(c)) = (in_array, cur.as_mut()) {
                             let mut px = 0.0;
                             let mut py = 0.0;
                             for attr in e.attributes().flatten() {
                                 let key = attr.key.as_ref();
                                 let val = attr
                                     .unescape_value()
                                     .unwrap_or_default()
                                     .into_owned();
                                 let f = val.parse::<f64>().unwrap_or(0.0);
                                 match key {
                                     b"x" => px = f,
                                     b"y" => py = f,
                                     _ => {}
                                 }
                             }
                             c.points.push((px, py));
                         }
                     }
                     _ => {}
                 }
             }
             Ok(Event::End(e)) => {
                 match e.name().as_ref() {

                     b"Array" => in_array = false,
                     b"mxCell" => {
                         if let Some(mut c) = cur.take() {
                             // fontSize 从 style 里拿不到的话用默认 11——style
                             // 在 mxCell 的 style 属性；这里回退解析不了就默认。
                             c.font_size = 11.0;
                             if c.id != "0" && c.id != "1" {
                                 cells.push(c);
                             }
                         }
                     }
                     _ => {}
                 }
             }
             Ok(Event::Empty(e)) => {
                 // 自闭合标签（如 <mxGeometry …/>）是 Empty 事件而非 Start+End
                 match e.name().as_ref() {
                     b"mxGeometry" => {
                         if let Some(c) = cur.as_mut() {
                             for attr in e.attributes().flatten() {
                                 let key = attr.key.as_ref();
                                 let val = attr
                                     .unescape_value()
                                     .unwrap_or_default()
                                     .into_owned();
                                 let f = val.parse::<f64>().unwrap_or(0.0);
                                 match key {
                                     b"x" => c.x = f,
                                     b"y" => c.y = f,
                                     b"width" => c.w = f,
                                     b"height" => c.h = f,
                                     _ => {}
                                 }
                             }
                         }
                     }
                     b"mxPoint" => {
                         if let (true, Some(c)) = (in_array, cur.as_mut()) {
                             let mut px = 0.0;
                             let mut py = 0.0;
                             for attr in e.attributes().flatten() {
                                 let key = attr.key.as_ref();
                                 let val = attr
                                     .unescape_value()
                                     .unwrap_or_default()
                                     .into_owned();
                                 let f = val.parse::<f64>().unwrap_or(0.0);
                                 match key {
                                     b"x" => px = f,
                                     b"y" => py = f,
                                     _ => {}
                                 }
                             }
                             c.points.push((px, py));
                         }
                     }
                     _ => {}
                 }
             }
             Ok(Event::Eof) => break,
             Ok(_) => {}
             Err(e) => return Err(format!("xml parse error: {e}")),
         }
         buf.clear();
     }
     // 绝对坐标解析：mxGraph 里容器子元素的 x/y 是**相对父容器原点**的。
     // 不换算的话，跨父比较（重叠/交叉/越界/route 避障）全部失真——
     // 实测容器图里 lint 会漏报「边穿节点」。沿父链累加偏移；边不参与
     // 偏移链（边几何无坐标语义）。父链带访问守卫防环。
     {
         let idx: HashMap<&str, usize> = cells
             .iter()
             .enumerate()
             .map(|(i, c)| (c.id.as_str(), i))
             .collect();
         let abs = |start: usize| -> (f64, f64) {
             let (mut dx, mut dy) = (0.0, 0.0);
             let mut cur = Some(start);
             let mut guard = 0;
             while let Some(ci) = cur {
                 let c = &cells[ci];
                 if c.is_edge {
                     break;
                 }
                 dx += c.x;
                 dy += c.y;
                 cur = idx.get(c.parent.as_str()).copied();
                 guard += 1;
                 if guard > 64 {
                     break;
                 }
             }
             (dx, dy)
         };
         let offs: Vec<(f64, f64)> = (0..cells.len()).map(abs).collect();
         // 链和已含 cell 自身坐标 → 直接赋值（不是累加）
         for (c, &(dx, dy)) in cells.iter_mut().zip(&offs) {
             if !c.is_edge {
                 c.x = dx;
                 c.y = dy;
             }
         }
     }
     Ok((cells, page))
 }

 fn bbox_intersect(a: &GeomCell, b: &GeomCell) -> bool {
     a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h
 }

 /// 线段相交判定；相交返回交点坐标，否则 None。
 fn seg_intersect(
     (ax, ay): (f64, f64),
     (bx, by): (f64, f64),
     (cx, cy): (f64, f64),
     (dx, dy): (f64, f64),
 ) -> Option<(f64, f64)> {
     let cross = |(x1, y1): (f64, f64), (x2, y2): (f64, f64), (x3, y3): (f64, f64)| {
         (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1)
     };
     let d1 = cross((ax, ay), (bx, by), (cx, cy));
     let d2 = cross((ax, ay), (bx, by), (dx, dy));
     let d3 = cross((cx, cy), (dx, dy), (ax, ay));
     let d4 = cross((cx, cy), (dx, dy), (bx, by));
     let proper = ((d1 > 0.0 && d2 < 0.0) || (d1 < 0.0 && d2 > 0.0))
         && ((d3 > 0.0 && d4 < 0.0) || (d3 < 0.0 && d4 > 0.0));
     if !proper {
         return None;
     }
     // 交点：参数 t = 线1上点 = A + t(B-A)
     let denom = (ax - bx) * (cy - dy) - (ay - by) * (cx - dx);
     if denom.abs() < 1e-12 {
         return None;
     }
     let t = ((ax - cx) * (cy - dy) - (ay - cy) * (cx - dx)) / denom;
     Some((ax + t * (bx - ax), ay + t * (by - ay)))
 }

 /// 线段与矩形相交（Liang-Barsky），排除端点接触
 pub(crate) fn seg_rect_intersect(
     (x1, y1): (f64, f64),
     (x2, y2): (f64, f64),
     r: (f64, f64, f64, f64),
 ) -> bool {
     let (rx, ry, rw, rh) = r;
     let (mut t0, mut t1) = (0.0f64, 1.0f64);
     let dx = x2 - x1;
     let dy = y2 - y1;
     for (p, q) in [
         (-dx, x1 - rx),
         (dx, rx + rw - x1),
         (-dy, y1 - ry),
         (dy, ry + rh - y1),
     ] {
         if p == 0.0 {
             if q < 0.0 {
                 return false;
             }
         } else {
             let t = q / p;
             if p < 0.0 {
                 if t > t1 {
                     return false;
                 }
                 if t > t0 {
                     t0 = t;
                 }
             } else {
                 if t < t0 {
                     return false;
                 }
                 if t < t1 {
                     t1 = t;
                 }
             }
         }
     }
     // 相交部分长度 > 0.5 才算（端点接触不算）
     t0 < t1 && (t1 - t0) * dx.abs().max(dy.abs()) > 0.5
 }

 fn edge_segments(
     edge: &GeomCell,
     cells: &[GeomCell],
 ) -> Vec<((f64, f64), (f64, f64))> {
     let center = |id: &str| -> Option<(f64, f64)> {
         cells
             .iter()
             .find(|c| c.id == id)
             .map(|c| (c.x + c.w / 2.0, c.y + c.h / 2.0))
     };
     let mut pts: Vec<(f64, f64)> = Vec::new();
     if let Some(s) = edge.source.as_ref().and_then(|id| center(id)) {
         pts.push(s);
     }
     pts.extend(edge.points.iter().copied());
     if let Some(t) = edge.target.as_ref().and_then(|id| center(id)) {
         pts.push(t);
     }
     pts.windows(2)
         .map(|w| (w[0], w[1]))
         .collect()
 }

 /// 祖先链（用于跳过容器与子元素的"重叠"误报）
 pub(crate) fn is_ancestor(a: &str, b: &str, cells: &[GeomCell]) -> bool {
     let mut cur = b;
     let mut guard = 0;
     while guard < 64 {
         match cells.iter().find(|c| c.id == cur) {
             Some(c) if c.parent == a => return true,
             Some(c) => cur = &c.parent,
             None => return false,
         }
         guard += 1;
     }
     false
 }

 /// 估算标签文字需要的宽度（CJK ≈ fontSize，拉丁 ≈ 0.55×fontSize）
 fn est_label_width(value: &str, font_size: f64) -> f64 {
     value
         .chars()
         .map(|ch| {
             if ch.is_ascii() {
                 0.55 * font_size
             } else {
                 font_size
             }
         })
         .sum()
 }

