 /// Render options for a single diagram export.
 #[derive(Debug, Clone)]
 pub struct RenderOptions {
     /// Output pixel scale multiplier (1.0 = native, 2.0 = retina).
     pub scale: f64,
     /// Background CSS color (e.g. `"#ffffff"`). Empty string = transparent.
     pub background: String,
     /// Optional border padding in pixels around the diagram.
     pub border: u32,
     /// 叠加数字/id 徽章标注（碰撞避让；仅污染导出图，不碰文件）。
     pub annotate: bool,
     /// 只导出这些 cell 的包围盒区域（放大视图；空 = 全图）。
     pub focus: Vec<String>,
     /// 若设置：渲染出的 PNG 另存到该目录（复盘/调试用）。
     pub trace_dir: Option<String>,
 }

 impl Default for RenderOptions {
     fn default() -> Self {
         Self {
             scale: 1.0,
             background: "#ffffff".into(),
             border: 10,
             annotate: false,
             focus: Vec::new(),
             trace_dir: None,
         }
     }
 }

 /// Errors surfaced by the renderer.
 #[derive(Debug, Error)]
 pub enum RenderError {
     #[error("browser: {0}")]
     Browser(String),
     #[error("page: {0}")]
     Page(String),
     #[error("xml: {0}")]
     Xml(String),
     #[error("export: {0}")]
     Export(String),
 }

 /// Pluggable rendering backend. Implementations may drive a real browser
 /// (production) or return canned bytes (tests).
 #[async_trait]
 pub trait RenderDriver: Send + Sync {
     async fn render(
         &self,
         xml: &str,
         opts: &RenderOptions,
     ) -> Result<Vec<u8>, RenderError>;
+
+    /// libavoid 避障正交布线（可选能力）：返回改写后的完整 mxfile XML。
+    /// 默认不支持（mock 等轻量驱动）——调用方应回退到确定性兜底路由。
+    async fn reroute(&self, _xml: &str) -> Result<String, RenderError> {
+        Err(RenderError::Export("reroute unsupported by this driver".into()))
+    }
 }

 /// The main entry point. Holds a shared driver and forwards calls.
 #[derive(Clone)]
 pub struct Renderer {
     driver: Arc<dyn RenderDriver>,
 }

 impl std::fmt::Debug for Renderer {
     fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
         f.debug_struct("Renderer").field("driver", &"<dyn RenderDriver>").finish()
     }
 }

 impl Renderer {
     pub fn new(driver: Arc<dyn RenderDriver>) -> Self {
         Self { driver }
     }

     /// Render a Draw.io XML diagram to PNG bytes.
     pub async fn render(
         &self,
         xml: &str,
         opts: &RenderOptions,
     ) -> Result<Vec<u8>, RenderError> {
         if xml.trim().is_empty() {
             return Err(RenderError::Xml("empty XML input".into()));
         }
         let png = self.driver.render(xml, opts).await?;
         if let Some(dir) = &opts.trace_dir {
             let dir = std::path::Path::new(dir);
             let _ = std::fs::create_dir_all(dir);
             let name = format!(
                 "trace-{}.png",
                 std::time::SystemTime::now()
                     .duration_since(std::time::UNIX_EPOCH)
                     .map(|d| d.as_millis())
                     .unwrap_or(0)
             );
             let _ = std::fs::write(dir.join(name), &png);
         }
         Ok(png)
     }
+
+    /// libavoid 避障正交布线：驱动支持时返回改写后的完整 mxfile XML；
+    /// 不支持/失败由调用方回退到确定性兜底路由。
+    pub async fn reroute(&self, xml: &str) -> Result<String, RenderError> {
+        self.driver.reroute(xml).await
+    }
 }

