/// 返回改写后的完整 mxfile XML。与 render 共享页面与串行锁。
pub async fn reroute(&self, xml: &str) -> Result<String, RenderError> {
    if xml.trim().is_empty() { return Err(RenderError::Xml("empty xml".into())); }
    let _guard = self.inner.render_lock.lock().await;
