 /// Result of an applied edit, reported back to the model so it knows exactly
 /// what changed (locality feedback instead of protocol enforcement).
 #[derive(Debug, Default, Clone)]
 pub struct EditReport {
     pub noop: bool,
     pub added: Vec<String>,
     pub removed: Vec<String>,
     pub changed: Vec<String>,
     /// Changed cells whose span does NOT touch the edited line range.
     pub off_range: Vec<String>,
     pub unchanged: usize,
 }

 /// Loaded, canonical document with its span index.
 #[derive(Debug, Clone)]
 pub struct XmlDoc {
     pub path: PathBuf,
     pub text: String,
     /// Span index (cell id -> line range), built lazily on first access and
     /// invalidated whenever `text` changes. `text` is the single source of
     /// truth; this is a pure cache.
     cells: OnceLock<Vec<CellSpan>>,
     /// Rolling undo stack of previous canonical texts (most recent first).
     history: Vec<String>,
     /// 2018 回退兼容模式。构造时确定，之后 apply_edit/apply_edits 沿用，
     /// 保证同一文档生命周期内规范化行为一致。
     legacy_mode: bool,
 }

