       drawioXmlDirty = true;
       drawioSyncTimer = setTimeout(syncDrawioXml, 3000);
     }
   } catch (e) {
     drawioXmlDirty = true;
     drawioSyncTimer = setTimeout(syncDrawioXml, 3000);
   }
 }

 function drawioLoad(xml) {
