    pub fn apply_edit(
        &mut self,
        start: usize,
        end: usize,
        replacement: &str,
    ) -> Result<EditReport, XmlError> {
        let total = total_lines(&self.text);
        if start < 1 || end < start || end > total {
            return Err(XmlError::BadRange(format!(
                "{start}-{end} (file has {total} lines)"
