        let cells = index(&canonical)?;
        // 引用完整性：只拒绝**新产生**的断引用（既有断引用不阻塞）。
        reject_new_broken_refs(&self.text, self.cells(), &canonical, &cells)?;
        let before = content_map(&self.text, self.cells());
        let after = content_map(&canonical, &cells);
        let mut report = EditReport {
            noop: false,
            ..EditReport::default()
        };
        let mut ids = BTreeSet::new();
        for id in before.keys() {
            ids.insert(id.clone());
        }
        for id in after.keys() {
            ids.insert(id.clone());
        }
        for id in &ids {
            match (before.get(id), after.get(id)) {
                (None, Some(_)) => report.added.push(id.clone()),
                (Some(_), None) => report.removed.push(id.clone()),
                (Some(a), Some(b)) => {
                    if a != b {
                        report.changed.push(id.clone());
                    } else {
                        report.unchanged += 1;
                    }
                }
                (None, None) => {}
            }
        }
        // off_range：changed cell 的**前置** span 是否触及任一请求区间。
        // 必须用前置 span——本次插入/删除会使后置 span 整体漂移，用后置
        // span 会把模型明确请求过的 cell 误报为越界（E2E 实测）。
        let ranges: Vec<(usize, usize)> = edits.iter().map(|(s, e, _)| (*s, *e)).collect();
        for id in &report.changed {
            let Some(span) = self.cells().iter().find(|c| &c.id == id) else {
                continue;
            };
            let touches = ranges
                .iter()
                .any(|&(s, e)| !(span.end_line < s || span.start_line > e));
            if !touches {
                report.off_range.push(id.clone());
            }
        }
        self.history.push(std::mem::replace(&mut self.text, canonical));
        if self.history.len() > 10 {
            self.history.remove(0);
        }
        self.cells = OnceLock::from(cells);
        Ok(report)
    }

    pub fn undo(&mut self) -> Option<String> {
        let prev = self.history.pop()?;
        self.text = prev;
        self.cells = OnceLock::from(index(&self.text).ok()?);
        Some(self.text.clone())
    }

}

