             }
             bad_tools = 0;
             let args = env.get("args").cloned().unwrap_or(json!({}));
             let args_key = serde_json::to_string(&args).unwrap_or_default();
             // 同参重复调用守卫：连续两次「同工具同参数且上次成功」的调用
             // 结果不会变化，多半是模型在空转兜圈（实测曾以 read query 循环
