 }

 use serde_json::{Value, json};

 /// 无进展判定：no-op / 工具失败 / view 未变化算原地踏步的一步；
 /// read/check/view(渲染成功) 算有进展——信息增益也是进展。
 fn is_no_progress_text(t: &str) -> bool {
     t.starts_with("工具执行失败")
         || t.starts_with("no-op")
         || t.contains("未变化")
         || t.contains("未修改")
 }

