/// Check budget guard.
pub fn check_budget(
    spent: f64,
    opts: &RunOpts,
) -> Option<String> {
    if opts.budget_remaining.is_finite() && spent >= opts.budget_remaining {
        Some(format!(
            "会话预算已用尽（本次已花 ¥{spent:.4} ≥ 预算 ¥{:.2}）。\
             可在 ⚙ 设置里调高预算后继续。",
            opts.budget_remaining
        ))
    } else {
        None
    }
}

